responseSchemaJson:
{
  "type": "object",
  "description": "剧本创作大师的核心任务是基于角色和世界观设定，构思一段最符合要求的开局/前情提要（楔子）正文。所有输出必须为简体中文(zh-CN)。",
  "properties": {
    "scriptOpening": {
      "type": "object",
      "description": "最佳开局方案。",
      "properties": {
        "content": {
          "type": "string",
          "description": "具体的开局文本或旁白内容，作为故事的起点（前情提要）。情节紧凑，结构~松散，多自然段。"
        }
      },
      "required": [
        "content"
      ],
      "propertyOrdering": [
        "content"
      ]
    },
    "test": {
      "type": "object",
      "description": "[测试模块] 包含用于评估模型特定能力的附加任务。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "scriptOpening",
    "test"
  ],
  "propertyOrdering": [
    "scriptOpening",
    "test"
  ]
}

responseSchemaParserJs:
const rawText = responseJson.candidates[0].content.parts[0].text;
const jsonString = rawText.substring(rawText.indexOf('{'), rawText.lastIndexOf('}') + 1);
const data = JSON.parse(jsonString);
const actions = data.scriptOpening.content.split('\n').map(l => l.trim()).filter(Boolean).map(c => ({ type: 'description', content: c }));
return { processedTurnActions: actions, originalData: data };
